# owner: platform
"""Lay students out in rows for a printed seating chart."""

from typing import List, Tuple

from rosterkit.models import Student

def last_then_first(student: Student) -> Tuple[str, str]:
    """Sort key: last name, first name breaks ties."""
    return (student.last_name, student.first_name)

def check_layout(
    students: List[Student], seats_per_row: int
) -> None:
    if seats_per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def chunk_students(
    ordered: List[Student], size: int
) -> List[List[Student]]:
    starts = range(0, len(ordered), size)
    return [ordered[start:start + size] for start in starts]

def format_row(number: int, group: List[Student]) -> str:
    labels = [student.display_name for student in group]
    return f"Row {number}: " + " | ".join(labels)

def format_rows(groups: List[List[Student]]) -> List[str]:
    texts = []
    for number, group in enumerate(groups, start=1):
        texts.append(format_row(number, group))
    return texts

def seat_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    check_layout(students, seats_per_row)
    ordered = sorted(students, key=last_then_first)
    groups = chunk_students(ordered, seats_per_row)
    return format_rows(groups)
